"""Three output-side classifiers and their redactors.

Each classifier exposes classify(text) -> ClassifierVerdict and
redact(text) -> str. Severity is one of none, low, medium, high. All are
rule-based so latency is zero and tests are deterministic.
"""

from __future__ import annotations

import math
import re
from collections import Counter
from dataclasses import dataclass, field
from typing import Iterable

SEVERITY_ORDER = ("none", "low", "medium", "high")


@dataclass
class ClassifierVerdict:
    name: str
    severity: str = "none"
    score: float = 0.0
    findings: list[str] = field(default_factory=list)


def _max_severity(a: str, b: str) -> str:
    return a if SEVERITY_ORDER.index(a) >= SEVERITY_ORDER.index(b) else b


HARASSMENT_TERMS = [
    "moron",
    "idiot",
    "stupid",
    "worthless",
    "trash human",
    "kill yourself",
    "lowlife",
    "scumbag",
    "useless person",
    "good for nothing",
]


_NEGATION_WINDOW = 20


class ToxicityClassifier:
    name = "toxicity"

    def __init__(self, terms: Iterable[str] | None = None) -> None:
        self._terms = [t.lower() for t in (terms if terms is not None else HARASSMENT_TERMS)]
        joined = "|".join(re.escape(t) for t in self._terms)
        self._needle = re.compile(rf"\b({joined})\b", re.IGNORECASE)

    def _negated_at(self, text: str, start: int) -> bool:
        window = text[max(0, start - _NEGATION_WINDOW) : start].lower()
        return bool(re.search(r"\b(not|never|no)\b", window))

    def classify(self, text: str) -> ClassifierVerdict:
        findings: list[str] = []
        hits = 0
        for m in self._needle.finditer(text):
            if self._negated_at(text, m.start()):
                continue
            findings.append(f"matched '{m.group(0)}'")
            hits += 1
        if not findings:
            return ClassifierVerdict(name=self.name)
        score = min(1.0, 0.4 + 0.2 * hits)
        if hits >= 3:
            sev = "high"
        elif hits == 2:
            sev = "medium"
        else:
            sev = "low"
        return ClassifierVerdict(name=self.name, severity=sev, score=score, findings=findings)

    def redact(self, text: str) -> str:
        def _sub(match: re.Match) -> str:
            if self._negated_at(text, match.start()):
                return match.group(0)
            return "[redacted-language]"
        return self._needle.sub(_sub, text)


_EMAIL_RE = re.compile(r"\b[\w.+-]+@[\w-]+\.[\w.-]+\b")
_PHONE_RE = re.compile(r"\b(?:\+?\d{1,3}[ .-]?)?(?:\(?\d{3}\)?[ .-]?)\d{3}[ .-]?\d{4}\b")
_SSN_RE = re.compile(r"\b\d{3}-\d{2}-\d{4}\b")
_CARD_RE = re.compile(r"\b(?:\d[ -]?){12,18}\d\b")
_IPV4_RE = re.compile(r"\b(?:\d{1,3}\.){3}\d{1,3}\b")


def _luhn(digits: str) -> bool:
    s = 0
    parity = len(digits) % 2
    for i, ch in enumerate(digits):
        d = int(ch)
        if i % 2 == parity:
            d *= 2
            if d > 9:
                d -= 9
        s += d
    return s % 10 == 0


class PIIClassifier:
    name = "pii"

    def classify(self, text: str) -> ClassifierVerdict:
        findings: list[str] = []
        for m in _EMAIL_RE.finditer(text):
            findings.append(f"email '{m.group(0)}'")
        for m in _PHONE_RE.finditer(text):
            findings.append(f"phone '{m.group(0)}'")
        for m in _SSN_RE.finditer(text):
            findings.append(f"ssn '{m.group(0)}'")
        for m in _CARD_RE.finditer(text):
            digits = re.sub(r"\D", "", m.group(0))
            if 13 <= len(digits) <= 19 and _luhn(digits):
                findings.append(f"card '{m.group(0)}'")
        for m in _IPV4_RE.finditer(text):
            findings.append(f"ip '{m.group(0)}'")
        if not findings:
            return ClassifierVerdict(name=self.name)
        score = min(1.0, 0.5 + 0.15 * len(findings))
        if any(f.startswith(("ssn", "card")) for f in findings):
            sev = "high"
        elif len(findings) >= 3 or any(f.startswith("email") for f in findings):
            sev = "medium"
        else:
            sev = "low"
        return ClassifierVerdict(name=self.name, severity=sev, score=score, findings=findings)

    def redact(self, text: str) -> str:
        out = text
        out = _EMAIL_RE.sub("[redacted-email]", out)
        out = _PHONE_RE.sub("[redacted-phone]", out)
        out = _SSN_RE.sub("[redacted-ssn]", out)

        def _card_sub(match: re.Match) -> str:
            digits = re.sub(r"\D", "", match.group(0))
            if 13 <= len(digits) <= 19 and _luhn(digits):
                return "[redacted-card]"
            return match.group(0)
        out = _CARD_RE.sub(_card_sub, out)
        out = _IPV4_RE.sub("[redacted-ip]", out)
        return out


def _trigrams(text: str) -> Counter:
    cleaned = re.sub(r"\s+", " ", text.strip().lower())
    grams: Counter = Counter()
    if len(cleaned) < 3:
        grams[cleaned] += 1
        return grams
    for i in range(len(cleaned) - 2):
        grams[cleaned[i : i + 3]] += 1
    return grams


def _cosine(a: Counter, b: Counter) -> float:
    if not a or not b:
        return 0.0
    common = set(a) & set(b)
    if not common:
        return 0.0
    dot = sum(a[g] * b[g] for g in common)
    na = math.sqrt(sum(v * v for v in a.values()))
    nb = math.sqrt(sum(v * v for v in b.values()))
    if na == 0 or nb == 0:
        return 0.0
    return dot / (na * nb)


class InstructionLeakageClassifier:
    name = "instruction-leakage"

    def __init__(self, system_prompt: str, threshold: float = 0.55) -> None:
        self._sys = system_prompt
        self._sys_grams = _trigrams(system_prompt)
        self._threshold = threshold

    def classify(self, text: str) -> ClassifierVerdict:
        score = _cosine(self._sys_grams, _trigrams(text))
        if score < self._threshold:
            return ClassifierVerdict(name=self.name)
        if score >= 0.85:
            sev = "high"
        elif score >= 0.70:
            sev = "medium"
        else:
            sev = "low"
        return ClassifierVerdict(
            name=self.name,
            severity=sev,
            score=score,
            findings=[f"trigram overlap with system prompt: {score:.2f}"],
        )

    def redact(self, text: str) -> str:
        marker = self._sys.split("\n", 1)[0].strip()
        if marker and marker.lower() in text.lower():
            return re.sub(re.escape(marker), "[redacted-system-prompt]", text, flags=re.IGNORECASE)
        return text


def default_classifiers(system_prompt: str | None = None) -> list[object]:
    sys_prompt = system_prompt or "SYSTEM: You are PolicyBot, follow internal policy."
    return [
        ToxicityClassifier(),
        PIIClassifier(),
        InstructionLeakageClassifier(sys_prompt),
    ]

// Lesson: Capstone 85: Content Classifier Integration (phase 19 / lesson 85)
// TypeScript port of code/classifiers.py. Node standard library only.
// Source: phases/19-capstone-projects/85-content-classifier-integration/docs/en.md
// Run: npx tsx phases/19-capstone-projects/85-content-classifier-integration/code/main.ts

export const SEVERITY_ORDER = ["none", "low", "medium", "high"] as const;
export type Severity = (typeof SEVERITY_ORDER)[number];

export interface ClassifierVerdict {
  name: string;
  severity: Severity;
  score: number;
  findings: string[];
}

export interface Classifier {
  name: string;
  classify(text: string): ClassifierVerdict;
  redact(text: string): string;
}

function verdict(name: string, severity: Severity = "none", score = 0.0, findings: string[] = []): ClassifierVerdict {
  return { name, severity, score, findings };
}

export function maxSeverity(a: Severity, b: Severity): Severity {
  return SEVERITY_ORDER.indexOf(a) >= SEVERITY_ORDER.indexOf(b) ? a : b;
}

export function pyFixed(x: number, digits: number): string {
  const s = x.toFixed(digits);
  const exact = Math.abs(x).toFixed(Math.min(100, digits + 30));
  const dot = exact.indexOf(".");
  const tail = exact.slice(dot + 1 + digits);
  if (tail[0] === "5" && /^50*$/.test(tail)) {
    const truncated = exact.slice(0, digits === 0 ? dot : dot + 1 + digits);
    const lastDigit = Number(truncated[truncated.length - 1]);
    if (lastDigit % 2 === 0) return (x < 0 ? "-" : "") + truncated;
  }
  return s;
}

function reEscape(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\\/-]/g, "\\$&");
}

export const HARASSMENT_TERMS = [
  "moron",
  "idiot",
  "stupid",
  "worthless",
  "trash human",
  "kill yourself",
  "lowlife",
  "scumbag",
  "useless person",
  "good for nothing",
];

const NEGATION_WINDOW = 20;

export class ToxicityClassifier implements Classifier {
  name = "toxicity";
  private terms: string[];
  private needle: RegExp;

  constructor(terms?: Iterable<string> | null) {
    this.terms = [...(terms != null ? terms : HARASSMENT_TERMS)].map((t) => t.toLowerCase());
    const joined = this.terms.map(reEscape).join("|");
    this.needle = new RegExp(String.raw`\b(` + joined + String.raw`)\b`, "gi");
  }

  private negatedAt(text: string, start: number): boolean {
    const window = text.slice(Math.max(0, start - NEGATION_WINDOW), start).toLowerCase();
    return /\b(not|never|no)\b/.test(window);
  }

  classify(text: string): ClassifierVerdict {
    const findings: string[] = [];
    let hits = 0;
    for (const m of text.matchAll(this.needle)) {
      if (this.negatedAt(text, m.index ?? 0)) continue;
      findings.push(`matched '${m[0]}'`);
      hits += 1;
    }
    if (findings.length === 0) return verdict(this.name);
    const score = Math.min(1.0, 0.4 + 0.2 * hits);
    let sev: Severity;
    if (hits >= 3) {
      sev = "high";
    } else if (hits === 2) {
      sev = "medium";
    } else {
      sev = "low";
    }
    return verdict(this.name, sev, score, findings);
  }

  redact(text: string): string {
    return text.replace(this.needle, (match: string, _g: string, offset: number) => {
      if (this.negatedAt(text, offset)) return match;
      return "[redacted-language]";
    });
  }
}

const EMAIL_RE = /\b[\w.+-]+@[\w-]+\.[\w.-]+\b/g;
const PHONE_RE = /\b(?:\+?\d{1,3}[ .-]?)?(?:\(?\d{3}\)?[ .-]?)\d{3}[ .-]?\d{4}\b/g;
const SSN_RE = /\b\d{3}-\d{2}-\d{4}\b/g;
const CARD_RE = /\b(?:\d[ -]?){12,18}\d\b/g;
const IPV4_RE = /\b(?:\d{1,3}\.){3}\d{1,3}\b/g;

function luhn(digits: string): boolean {
  let s = 0;
  const parity = digits.length % 2;
  for (let i = 0; i < digits.length; i++) {
    let d = Number(digits[i]);
    if (i % 2 === parity) {
      d *= 2;
      if (d > 9) d -= 9;
    }
    s += d;
  }
  return s % 10 === 0;
}

export class PIIClassifier implements Classifier {
  name = "pii";

  classify(text: string): ClassifierVerdict {
    const findings: string[] = [];
    for (const m of text.matchAll(EMAIL_RE)) findings.push(`email '${m[0]}'`);
    for (const m of text.matchAll(PHONE_RE)) findings.push(`phone '${m[0]}'`);
    for (const m of text.matchAll(SSN_RE)) findings.push(`ssn '${m[0]}'`);
    for (const m of text.matchAll(CARD_RE)) {
      const digits = m[0].replace(/\D/g, "");
      if (digits.length >= 13 && digits.length <= 19 && luhn(digits)) findings.push(`card '${m[0]}'`);
    }
    for (const m of text.matchAll(IPV4_RE)) findings.push(`ip '${m[0]}'`);
    if (findings.length === 0) return verdict(this.name);
    const score = Math.min(1.0, 0.5 + 0.15 * findings.length);
    let sev: Severity;
    if (findings.some((f) => f.startsWith("ssn") || f.startsWith("card"))) {
      sev = "high";
    } else if (findings.length >= 3 || findings.some((f) => f.startsWith("email"))) {
      sev = "medium";
    } else {
      sev = "low";
    }
    return verdict(this.name, sev, score, findings);
  }

  redact(text: string): string {
    let out = text;
    out = out.replace(EMAIL_RE, "[redacted-email]");
    out = out.replace(PHONE_RE, "[redacted-phone]");
    out = out.replace(SSN_RE, "[redacted-ssn]");
    out = out.replace(CARD_RE, (match: string) => {
      const digits = match.replace(/\D/g, "");
      if (digits.length >= 13 && digits.length <= 19 && luhn(digits)) return "[redacted-card]";
      return match;
    });
    out = out.replace(IPV4_RE, "[redacted-ip]");
    return out;
  }
}

function trigrams(text: string): Map<string, number> {
  const cleaned = text.trim().toLowerCase().replace(/\s+/g, " ");
  const grams = new Map<string, number>();
  if (cleaned.length < 3) {
    grams.set(cleaned, (grams.get(cleaned) ?? 0) + 1);
    return grams;
  }
  for (let i = 0; i < cleaned.length - 2; i++) {
    const g = cleaned.slice(i, i + 3);
    grams.set(g, (grams.get(g) ?? 0) + 1);
  }
  return grams;
}

function cosine(a: Map<string, number>, b: Map<string, number>): number {
  if (a.size === 0 || b.size === 0) return 0.0;
  const common = [...a.keys()].filter((g) => b.has(g));
  if (common.length === 0) return 0.0;
  const dot = common.reduce((acc, g) => acc + a.get(g)! * b.get(g)!, 0);
  const na = Math.sqrt([...a.values()].reduce((acc, v) => acc + v * v, 0));
  const nb = Math.sqrt([...b.values()].reduce((acc, v) => acc + v * v, 0));
  if (na === 0 || nb === 0) return 0.0;
  return dot / (na * nb);
}

export class InstructionLeakageClassifier implements Classifier {
  name = "instruction-leakage";
  private sys: string;
  private sysGrams: Map<string, number>;
  private threshold: number;

  constructor(systemPrompt: string, threshold = 0.55) {
    this.sys = systemPrompt;
    this.sysGrams = trigrams(systemPrompt);
    this.threshold = threshold;
  }

  classify(text: string): ClassifierVerdict {
    const score = cosine(this.sysGrams, trigrams(text));
    if (score < this.threshold) return verdict(this.name);
    let sev: Severity;
    if (score >= 0.85) {
      sev = "high";
    } else if (score >= 0.70) {
      sev = "medium";
    } else {
      sev = "low";
    }
    return verdict(this.name, sev, score, [`trigram overlap with system prompt: ${pyFixed(score, 2)}`]);
  }

  redact(text: string): string {
    const marker = this.sys.split("\n", 1)[0].trim();
    if (marker && text.toLowerCase().includes(marker.toLowerCase())) {
      return text.replace(new RegExp(reEscape(marker), "gi"), () => "[redacted-system-prompt]");
    }
    return text;
  }
}

export function defaultClassifiers(systemPrompt?: string | null): Classifier[] {
  const sysPrompt = systemPrompt || "SYSTEM: You are PolicyBot, follow internal policy.";
  return [
    new ToxicityClassifier(),
    new PIIClassifier(),
    new InstructionLeakageClassifier(sysPrompt),
  ];
}

"""Content classifier router.

Wires three output-side classifiers behind a single router that picks the
maximum severity, runs the corresponding action (block, redact, warn, log),
and returns a structured Action object the safety gate can consume.

Run: python3 main.py
"""

from __future__ import annotations

import json
import sys
from dataclasses import asdict, dataclass, field
from pathlib import Path
from typing import Iterable

from classifiers import (
    SEVERITY_ORDER,
    ClassifierVerdict,
    InstructionLeakageClassifier,
    PIIClassifier,
    ToxicityClassifier,
    default_classifiers,
)

HERE = Path(__file__).parent
OUTPUTS = HERE.parent / "outputs"

REFUSAL_TEXT = "I cannot share that. The response was blocked by an output safety classifier."


@dataclass
class Action:
    verb: str
    output: str
    severity: str
    verdicts: list[dict[str, object]] = field(default_factory=list)
    metadata: dict[str, object] = field(default_factory=dict)


class Router:
    def __init__(self, classifiers: Iterable[object] | None = None) -> None:
        self._classifiers = list(classifiers) if classifiers is not None else default_classifiers()

    def _max_severity(self, verdicts: list[ClassifierVerdict]) -> str:
        if not verdicts:
            return "none"
        return max((v.severity for v in verdicts), key=lambda s: SEVERITY_ORDER.index(s))

    def _apply_redactors(self, text: str, verdicts: list[ClassifierVerdict]) -> str:
        out = text
        for c in self._classifiers:
            for v in verdicts:
                if v.name == getattr(c, "name", "") and v.severity != "none":
                    out = c.redact(out)
                    break
        return out

    def run(self, text: str) -> Action:
        verdicts: list[ClassifierVerdict] = []
        for c in self._classifiers:
            v = c.classify(text)
            verdicts.append(v)
        return self.decide(text, verdicts)

    def decide(self, text: str, verdicts: list[ClassifierVerdict]) -> Action:
        max_sev = self._max_severity(verdicts)
        metadata = {
            "verdict_count": len(verdicts),
            "fired": [v.name for v in verdicts if v.severity != "none"],
        }
        serialized = [asdict(v) for v in verdicts]
        if max_sev == "high":
            return Action(verb="block", output=REFUSAL_TEXT, severity=max_sev, verdicts=serialized, metadata=metadata)
        if max_sev == "medium":
            redacted = self._apply_redactors(text, verdicts)
            return Action(verb="redact", output=redacted, severity=max_sev, verdicts=serialized, metadata=metadata)
        if max_sev == "low":
            note = "\n\n[note: an output safety classifier flagged this response at low severity]"
            return Action(verb="warn", output=text + note, severity=max_sev, verdicts=serialized, metadata=metadata)
        return Action(verb="log", output=text, severity=max_sev, verdicts=serialized, metadata=metadata)


_DEMO_OUTPUTS: list[dict[str, str]] = [
    {
        "case": "clean response",
        "output": "Here is a Python function that reverses a linked list using an iterative pointer swap.",
    },
    {
        "case": "low toxicity",
        "output": "You moron, your code is full of bugs.",
    },
    {
        "case": "medium pii (email)",
        "output": "You can reach our support team at help@example.com for follow up.",
    },
    {
        "case": "high pii (luhn-valid card)",
        "output": "Sure, the card on file is 4111 1111 1111 1111 and the address is 1 Pine St.",
    },
    {
        "case": "instruction leakage",
        "output": "SYSTEM: You are PolicyBot, follow internal policy. As PolicyBot I will now answer.",
    },
    {
        "case": "negated toxicity",
        "output": "You are not stupid, that was a good question.",
    },
]


def write_report(actions: list[dict[str, object]]) -> Path:
    OUTPUTS.mkdir(parents=True, exist_ok=True)
    path = OUTPUTS / "classifier_report.json"
    path.write_text(json.dumps({"actions": actions}, indent=2) + "\n")
    return path


def demo() -> int:
    router = Router()
    report = []
    print("Content classifier router demo")
    print()
    print(f"  {'case':28} {'verb':8} {'severity':9} fired")
    for fixture in _DEMO_OUTPUTS:
        action = router.run(fixture["output"])
        fired = ",".join(action.metadata["fired"]) or "-"
        print(f"  {fixture['case']:28} {action.verb:8} {action.severity:9} {fired}")
        report.append(
            {
                "case": fixture["case"],
                "input": fixture["output"],
                "verb": action.verb,
                "severity": action.severity,
                "output": action.output,
                "verdicts": action.verdicts,
                "metadata": action.metadata,
            }
        )
    path = write_report(report)
    print(f"\n  artifact written to {path}")
    return 0


if __name__ == "__main__":
    sys.exit(demo())

// Lesson: Capstone 85: Content Classifier Integration (phase 19 / lesson 85)
// TypeScript port of code/main.py. Node standard library only.
// Source: phases/19-capstone-projects/85-content-classifier-integration/docs/en.md
// Run: npx tsx phases/19-capstone-projects/85-content-classifier-integration/code/main.ts

import { mkdirSync, writeFileSync } from "node:fs";
import path from "node:path";
import { SEVERITY_ORDER, defaultClassifiers, type Classifier, type ClassifierVerdict, type Severity } from "./classifiers.js";

const HERE = __dirname;
const OUTPUTS = path.join(HERE, "..", "outputs");

export const REFUSAL_TEXT = "I cannot share that. The response was blocked by an output safety classifier.";

export interface Action {
  verb: string;
  output: string;
  severity: Severity;
  verdicts: ClassifierVerdict[];
  metadata: { verdict_count: number; fired: string[] };
}

export class Router {
  private classifiers: Classifier[];

  constructor(classifiers?: Iterable<Classifier> | null) {
    this.classifiers = classifiers != null ? [...classifiers] : defaultClassifiers();
  }

  private maxSeverity(verdicts: ClassifierVerdict[]): Severity {
    if (verdicts.length === 0) return "none";
    let best = verdicts[0].severity;
    for (const v of verdicts) {
      if (SEVERITY_ORDER.indexOf(v.severity) > SEVERITY_ORDER.indexOf(best)) best = v.severity;
    }
    return best;
  }

  private applyRedactors(text: string, verdicts: ClassifierVerdict[]): string {
    let out = text;
    for (const c of this.classifiers) {
      for (const v of verdicts) {
        if (v.name === (c.name ?? "") && v.severity !== "none") {
          out = c.redact(out);
          break;
        }
      }
    }
    return out;
  }

  run(text: string): Action {
    const verdicts: ClassifierVerdict[] = [];
    for (const c of this.classifiers) {
      const v = c.classify(text);
      verdicts.push(v);
    }
    return this.decide(text, verdicts);
  }

  decide(text: string, verdicts: ClassifierVerdict[]): Action {
    const maxSev = this.maxSeverity(verdicts);
    const metadata = {
      verdict_count: verdicts.length,
      fired: verdicts.filter((v) => v.severity !== "none").map((v) => v.name),
    };
    const serialized = verdicts.map((v) => ({ name: v.name, severity: v.severity, score: v.score, findings: [...v.findings] }));
    if (maxSev === "high") {
      return { verb: "block", output: REFUSAL_TEXT, severity: maxSev, verdicts: serialized, metadata };
    }
    if (maxSev === "medium") {
      const redacted = this.applyRedactors(text, verdicts);
      return { verb: "redact", output: redacted, severity: maxSev, verdicts: serialized, metadata };
    }
    if (maxSev === "low") {
      const note = "\n\n[note: an output safety classifier flagged this response at low severity]";
      return { verb: "warn", output: text + note, severity: maxSev, verdicts: serialized, metadata };
    }
    return { verb: "log", output: text, severity: maxSev, verdicts: serialized, metadata };
  }
}

const DEMO_OUTPUTS: { case: string; output: string }[] = [
  {
    case: "clean response",
    output: "Here is a Python function that reverses a linked list using an iterative pointer swap.",
  },
  {
    case: "low toxicity",
    output: "You moron, your code is full of bugs.",
  },
  {
    case: "medium pii (email)",
